// CURTIR PUBLICAÇÃO

function curtir(botao) {

    const numero = botao.querySelector("span");

        let curtidas = parseInt(numero.textContent);

            curtidas++;

                numero.textContent = curtidas;

                    botao.style.color = "red";

                    }


                    // MOSTRAR COMENTÁRIOS

                    function mostrarComentarios(botao) {

                        const post = botao.closest(".post");

                            const comentarios = post.querySelector(".comentarios");

                                if (comentarios.style.display === "block") {

                                        comentarios.style.display = "none";

                                            } else {

                                                    comentarios.style.display = "block";

                                                        }

                                                        }


                                                        // ADICIONAR COMENTÁRIO

                                                        function comentar(evento, input) {

                                                            if (evento.key === "Enter") {

                                                                    const texto = input.value.trim();

                                                                            if (texto === "") {
                                                                                        return;
                                                                                                }

                                                                                                        const lista =
                                                                                                                    input.parentElement.querySelector(
                                                                                                                                    ".lista-comentarios"
                                                                                                                                                );

                                                                                                                                                        const comentario =
                                                                                                                                                                    document.createElement("div");

                                                                                                                                                                            comentario.classList.add("comentario");

                                                                                                                                                                                    comentario.textContent =
                                                                                                                                                                                                "Você: " + texto;

                                                                                                                                                                                                        lista.appendChild(comentario);

                                                                                                                                                                                                                input.value = "";

                                                                                                                                                                                                                    }

                                                                                                                                                                                                                    }


                                                                                                                                                                                                                    // CRIAR NOVA PUBLICAÇÃO

                                                                                                                                                                                                                    function criarPost() {

                                                                                                                                                                                                                        const input =
                                                                                                                                                                                                                                document.getElementById("novoPost");

                                                                                                                                                                                                                                    const texto = input.value.trim();

                                                                                                                                                                                                                                        if (texto === "") {

                                                                                                                                                                                                                                                alert("Digite alguma coisa!");

                                                                                                                                                                                                                                                        return;

                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                const feed =
                                                                                                                                                                                                                                                                        document.querySelector(".feed");

                                                                                                                                                                                                                                                                            const post =
                                                                                                                                                                                                                                                                                    document.createElement("article");

                                                                                                                                                                                                                                                                                        post.classList.add("post");

                                                                                                                                                                                                                                                                                            post.innerHTML = `

                                                                                                                                                                                                                                                                                                    <div class="post-header">

                                                                                                                                                                                                                                                                                                                <div class="avatar">
                                                                                                                                                                                                                                                                                                                                U
                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                        <strong>Você</strong>
                                                                                                                                                                                                                                                                                                                                                                                        <p>@usuario · agora</p>
                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="post-text">
                                                                                                                                                                                                                                                                                                                                                                                                                                ${texto}
                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="acoes">

                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onclick="curtir(this)">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ♡ <span>0</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button onclick="mostrarComentarios(this)">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    💬 <span>0</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ↗ Compartilhar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="comentarios">

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    placeholder="Escreva um comentário..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onkeydown="comentar(event, this)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="lista-comentarios"></div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const primeiroPost =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    feed.querySelector(".post");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        feed.insertBefore(post, primeiroPost);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            input.value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // SEGUIR USUÁRIO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function seguir(botao) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (botao.textContent === "Seguir") {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.textContent = "Seguindo";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.style.background = "#ddd";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.style.color = "#222";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.textContent = "Seguir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.style.background = "#222";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.style.color = "white";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // PESQUISAR POSTS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function pesquisar() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const pesquisa =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .getElementById("pesquisa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const posts =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".post");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            posts.forEach(function(post) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const texto =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                post.innerText.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (texto.includes(pesquisa)) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    post.style.display = "block";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        post.style.display = "none";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }